      sess=last.get('session_id'),cost=last.get('total_cost_usd') or 0,mu={m:[v.get(k,0) for k in K] for m,v in last['modelUsage'].items()},e=(e5,e1)))
print('1h share of cache writes (from usage.cache_creation):', g1/(g1+g5))
runs.sort(key=lambda r:r['t']); prev={}
agg=collections.defaultdict(lambda:collections.defaultdict(float))
for r in runs:
    p=prev.get(r['sess']); cum = p is not None and r['cost']>=p['cost']-1e-9 and all(r['mu'].get(m,[0]*4)[i]>=v[i] for m,v in p['mu'].items() for i in range(4))
    prev[r['sess']]=r
    e5,e1=r['e']; share1 = e1/(e5+e1) if e5+e1 else g1/(g1+g5)
    for m,v in r['mu'].items():
        d=[v[i]-(p['mu'].get(m,[0]*4)[i] if cum else 0) for i in range(4)]
        pi,po,pr,pw5,pw1=price(m)
        c=(d[0]*pi+d[1]*po+d[2]*pr+d[3]*((1-share1)*pw5+share1*pw1))/1e6
        cr=d[2]*pr/1e6; cw=d[3]*((1-share1)*pw5+share1*pw1)/1e6
        fam='Opus 5.5' if 'opus-5-5' in m else 'Opus 5' if 'opus-5' in m else 'Haiku 4.5'
        for key in [(r['label'],r['h']),(r['label'],'*'),('*','*'),('model',fam)]:
            a=agg[key]; a['in']+=d[0];a['out']+=d[1];a['cr']+=d[2];a['cw']+=d[3];a['cost']+=c;a['c_in']+=d[0]*pi/1e6;a['c_out']+=d[1]*po/1e6;a['c_cr']+=cr;a['c_cw']+=cw
    for key in [(r['label'],r['h']),(r['label'],'*'),('*','*')]: agg[key]['runs']+=1; agg[key]['reported_delta']+=r['cost']-(p['cost'] if cum else 0)
for k in sorted(agg,key=str):
    a=agg[k]; print(k,{x:(round(v,2) if x.startswith('c') or x=='reported_delta' else int(v)) for x,v in a.items()})
